{"path": "rest_api.py", "content": "import json


class RestAPI:
    def __init__(self, database=None):
        self.users = {}
        for user in (database or {}).get("users", []):
            self.users[user["name"]] = {
                "name": user["name"],
                "owes": dict(user.get("owes", {})),
                "owed_by": dict(user.get("owed_by", {})),
            }

    def _user_object(self, name):
        user = self.users[name]
        balance = sum(user["owed_by"].values()) - sum(user["owes"].values())
        return {
            "name": name,
            "owes": dict(sorted(user["owes"].items())),
            "owed_by": dict(sorted(user["owed_by"].items())),
            "balance": balance,
        }

    def _users_response(self, names):
        return json.dumps(
            {"users": [self._user_object(n) for n in sorted(names) if n in self.users]}
        )

    def get(self, url, payload=None):
        if url == "/users":
            if payload:
                data = json.loads(payload) if isinstance(payload, str) else payload
                return self._users_response(data.get("users", []))
            return self._users_response(self.users.keys())
        raise ValueError(f"unknown url: {url}")

    def post(self, url, payload=None):
        data = json.loads(payload) if isinstance(payload, str) else (payload or {})
        if url == "/add":
            name = data["user"]
            if name in self.users:
                raise ValueError(f"user already exists: {name}")
            self.users[name] = {"name": name, "owes": {}, "owed_by": {}}
            return json.dumps(self._user_object(name))
        if url == "/iou":
            lender, borrower, amount = data["lender"], data["borrower"], data["amount"]
            if lender not in self.users or borrower not in self.users:
                raise ValueError("unknown user")
            if lender == borrower:
                raise ValueError("lender and borrower must differ")
            self._add_debt(lender, borrower, amount)
            return self._users_response([lender, borrower])
        raise ValueError(f"unknown url: {url}")

    def _add_debt(self, lender, borrower, amount):
        lend, borr = self.users[lender], self.users[borrower]
        # Net against any existing debt in the other direction.
        net = borr["owed_by"].pop(lender, 0) - borr["owes"].pop(lender, 0) - amount
        lend["owes"].pop(borrower, None)
        lend["owed_by"].pop(borrower, None)
        # net > 0: lender still owes borrower; net < 0: borrower owes lender.
        if net > 0:
            lend["owes"][borrower] = net
            borr["owed_by"][lender] = net
        elif net < 0:
            borr["owes"][lender] = -net
            lend["owed_by"][borrower] = -net
